253	+/// BEGIN_ATTEMPT: ask the kernel for an attempt ID and a receive locator for one peer. An
254	+/// initiator passes no ID and the kernel picks one; a responder passes the ID of the INIT it was
255	+/// handed (the kernel refuses any other).
256	+pub fn begin_attempt(
257	+    mut req: Request,
258	+    slot: u8,
259	+    kernel_incarnation: &[u8; ATTR_PEER_INCARNATION_LEN],
260	+    given: Option<&[u8; ATTR_ATTEMPT_ID_LEN]>,
261	+) -> Result<Request, VptunnelError> {
262	+    req.put_u16(ATTR_PEER_SLOT, u16::from(slot))?;
263	+    req.put_bytes(ATTR_PEER_INCARNATION, kernel_incarnation)?;
264	+    if let Some(id) = given {
265	+        req.put_bytes(ATTR_ATTEMPT_ID, id)?;
266	+    }
267	+    Ok(req)
