270	+/// Decode the reply of BEGIN_ATTEMPT: the attempt ID and the receive locator the kernel issued.
271	+pub fn parse_attempt(payload: &[u8]) -> Result<([u8; ATTR_ATTEMPT_ID_LEN], u64), VptunnelError> {
272	+    let attrs = attributes(
273	+        payload
274	+            .get(4..)
275	+            .ok_or(VptunnelError::Malformed("attempt"))?,
276	+    )?;
277	+    let mut id = None;
278	+    let mut locator = None;
279	+    for a in &attrs {
280	+        match a.kind {
281	+            ATTR_ATTEMPT_ID => {
282	+                id = Some(
283	+                    <[u8; ATTR_ATTEMPT_ID_LEN]>::try_from(a.payload)
284	+                        .map_err(|_| VptunnelError::Malformed("attempt id"))?,
285	+                );
286	+            }
287	+            ATTR_LOCAL_RX => locator = Some(u64_of(a.payload, "locator")?),
288	+            _ => {}
289	+        }
290	+    }
291	+    match (id, locator) {
292	+        (Some(id), Some(l)) if l != 0 => Ok((id, l)),
293	+        _ => Err(VptunnelError::Malformed("attempt: missing id or locator")),
294	+    }
