34	/// One attempt's overall deadline, and the INIT retransmission intervals inside it.
35	pub const ATTEMPT_DEADLINE: Duration = Duration::from_secs(10);
36	const RETRANSMIT: [Duration; 4] = [
37	    Duration::from_millis(500),
38	    Duration::from_secs(1),
39	    Duration::from_secs(2),
40	    Duration::from_secs(4),
41	];
42	const BACKOFF: [Duration; 6] = [
43	    Duration::from_secs(1),
44	    Duration::from_secs(2),
45	    Duration::from_secs(4),
46	    Duration::from_secs(8),
47	    Duration::from_secs(16),
48	    Duration::from_secs(30),
49	];
50	/// How long the responder keeps the exact RESPONSE for a duplicate INIT.
51	pub const CACHE_LIFETIME: Duration = Duration::from_secs(20);
52	/// The initiator starts a new exchange this long after the last success, before the
53	/// kernel's 120 s soft key age.
54	pub const REKEY_AFTER: Duration = Duration::from_secs(90);
