56	#[derive(Debug, Error)]
57	#[error("{what}")]
58	pub struct PortError {
59	    pub what: String,
60	    /// The kernel's errno when the kernel rejected the request.
61	    pub errno: Option<i32>,
62	}
63	
64	/// The kernel operations the exchange needs.
65	pub trait Port {
66	    /// Ask the kernel for this attempt's ID and receive locator. The kernel chooses both; a
67	    /// responder passes the attempt ID of the INIT it was handed (`given`) and gets only a locator.
68	    fn begin_attempt(
69	        &mut self,
70	        slot: u8,
71	        kernel_incarnation: &[u8; INCARNATION_LEN],
72	        given: Option<&[u8; ATTEMPT_ID_LEN]>,
73	    ) -> Result<([u8; ATTEMPT_ID_LEN], u64), PortError>;
74	    /// Send one whole INIT or RESPONSE to the peer's configured endpoint.
75	    fn exchange_tx(&mut self, slot: u8, bytes: &[u8]) -> Result<(), PortError>;
76	    /// Install the directional keys and locators of a completed attempt, once.
77	    fn stage(
78	        &mut self,
79	        slot: u8,
80	        kernel_incarnation: &[u8; INCARNATION_LEN],
81	        keys: &SessionKeys,
82	    ) -> Result<(), PortError>;
83	    /// The kernel's current incarnation for a slot (after the kernel replaced the peer).
84	    fn kernel_incarnation(&mut self, slot: u8) -> Result<[u8; INCARNATION_LEN], PortError>;
85	}
