145	impl Controller {
146	    /// `kernel_incarnations` maps each configured slot to the kernel's incarnation of
147	    /// that peer (from STATUS after the commit).
148	    pub fn new(
149	        key: PrivateKey,
150	        config: &GatewayConfig,
151	        kernel_incarnations: &[(u8, [u8; INCARNATION_LEN])],
152	        mut rng: Entropy,
153	        log: Log,
154	        now: Instant,
155	    ) -> Self {
156	        let mut incarnation = [0u8; INCARNATION_LEN];
157	        while is_zero(&incarnation) {
158	            rng(&mut incarnation);
159	        }
160	        let peers = config
161	            .peers
162	            .iter()
163	            .map(|p| PeerCtl {
164	                name: p.name.clone(),
165	                slot: p.slot,
166	                public: p.public_key,
167	                role: p.role,
168	                path_budget: p.path_mtu,
169	                kernel_incarnation: kernel_incarnations
170	                    .iter()
171	                    .find(|(s, _)| *s == p.slot)
172	                    .map_or([0; INCARNATION_LEN], |(_, i)| *i),
173	                state: State::Idle { not_before: now },
174	                failures: 0,
175	                cached: None,
176	                rekey_requested: false,
177	            })
178	            .collect();
179	        Self {
180	            key,
181	            incarnation,
182	            peers,
183	            log,
184	            counts: Counts {
185	                established: 0,
186	                attempts_started: 0,
187	                attempts_failed: 0,
188	                rejected: 0,
189	                duplicates_answered: 0,
190	            },
191	            rekey_after: REKEY_AFTER,
192	        }
193	    }
194	
195	    /// Change the re-establishment interval (tests; the default is [`REKEY_AFTER`]).
196	    pub fn set_rekey_after(&mut self, d: Duration) {
197	        self.rekey_after = d;
198	    }
199	
200	    pub fn counts(&self) -> Counts {
201	        self.counts
202	    }
203	
204	    /// Is the exchange with this slot complete and still current?
205	    pub fn is_established(&self, slot: u8) -> bool {
206	        self.peers
207	            .iter()
208	            .any(|p| p.slot == slot && matches!(p.state, State::Established { .. }))
209	    }
210	
211	    fn say(&mut self, msg: String) {
212	        (self.log)(msg);
213	    }
214	
215	    /// The kernel issues the attempt ID and the receive locator. A kernel that replaced the peer
216	    /// (a disruptive change) is learned once, as for staging.
217	    fn begin_attempt<P: Port>(
218	        &mut self,
219	        i: usize,
220	        port: &mut P,
221	        given: Option<&[u8; ATTEMPT_ID_LEN]>,
222	    ) -> Result<([u8; ATTEMPT_ID_LEN], u64), PortError> {
223	        let slot = self.peers[i].slot;
224	        let mut r = port.begin_attempt(slot, &self.peers[i].kernel_incarnation, given);
225	        if matches!(&r, Err(e) if e.errno == Some(116)) {
226	            let inc = port.kernel_incarnation(slot)?;
227	            self.peers[i].kernel_incarnation = inc;
228	            r = port.begin_attempt(slot, &inc, given);
229	        }
230	        r
231	    }
232	
233	    /// Time-driven work: start attempts, retransmit INIT, expire attempts, re-establish.
234	    pub fn tick<P: Port>(&mut self, port: &mut P, now: Instant) {
235	        for i in 0..self.peers.len() {
236	            if self.peers[i].role != Role::Initiator {
237	                continue;
238	            }
239	            enum Action {
240	                None,
241	                Start,
242	                Retransmit,
243	                Expire,
244	            }
245	            let action = match &self.peers[i].state {
246	                State::Idle { not_before } if now >= *not_before => Action::Start,
247	                State::Idle { .. } => Action::None,
248	                State::Pending(p) if now.duration_since(p.started) >= ATTEMPT_DEADLINE => {
249	                    Action::Expire
250	                }
251	                State::Pending(p) if now >= p.next_retry => Action::Retransmit,
252	                State::Pending(_) => Action::None,
253	                State::Established { since }
254	                    if self.peers[i].rekey_requested
255	                        || now.duration_since(*since) >= self.rekey_after =>
256	                {
257	                    Action::Start
258	                }
259	                State::Established { .. } => Action::None,
260	            };
261	            match action {
262	                Action::None => {}
263	                Action::Start => self.start_attempt(i, port, now),
264	                Action::Retransmit => self.retransmit(i, port, now),
265	                Action::Expire => {
266	                    self.counts.attempts_failed += 1;
267	                    let f = self.peers[i].failures;
268	                    self.peers[i].failures += 1;
269	                    let wait = BACKOFF[f.min(BACKOFF.len() - 1)];
270	                    let name = self.peers[i].name.clone();
271	                    self.say(format!(
272	                        "attempt to {name} timed out; retrying in {}s",
273	                        wait.as_secs()
274	                    ));
275	                    self.peers[i].state = State::Idle {
276	                        not_before: now + wait,
277	                    };
278	                }
279	            }
280	        }
281	    }
282	
283	    /// Ask every established initiator peer for a new exchange now (key usage reached a limit).
284	    /// Responders cannot start one. Returns how many peers will start.
285	    pub fn request_rekey(&mut self) -> usize {
286	        let mut n = 0;
287	        for p in &mut self.peers {
288	            if p.role == Role::Initiator && matches!(p.state, State::Established { .. }) {
289	                p.rekey_requested = true;
290	                n += 1;
291	            }
292	        }
293	        n
294	    }
295	
296	    fn start_attempt<P: Port>(&mut self, i: usize, port: &mut P, now: Instant) {
297	        self.peers[i].rekey_requested = false;
298	        let (attempt_id, initiator_locator) = match self.begin_attempt(i, port, None) {
299	            Ok(x) => x,
300	            Err(e) => {
301	                self.fail_start(i, now, format!("cannot begin an attempt: {e}"));
302	                return;
303	            }
304	        };
305	        let payload = HandshakePayload {
306	            mode: Mode::Fresh,
307	            attempt_id,
308	            incarnation: self.incarnation,
309	            initiator_locator,
310	            responder_locator: 0,
311	            parent: [0; HASH_LEN],
312	            path_budget: self.peers[i].path_budget,
313	        };
314	        let initiator = match Initiator::start(&self.key, &self.peers[i].public, payload) {
315	            Ok(x) => x,
316	            Err(e) => {
317	                self.fail_start(i, now, format!("cannot build INIT: {e}"));
318	                return;
319	            }
320	        };
321	        let slot = self.peers[i].slot;
322	        if let Err(e) = port.exchange_tx(slot, initiator.init_bytes()) {
323	            self.fail_start(i, now, format!("cannot send INIT: {e}"));
324	            return;
325	        }
326	        self.counts.attempts_started += 1;
327	        let name = self.peers[i].name.clone();
328	        self.say(format!("sent INIT to {name}"));
329	        self.peers[i].state = State::Pending(Box::new(Pending {
330	            initiator,
331	            started: now,
332	            next_retry: now + RETRANSMIT[0],
333	            retries: 0,
334	        }));
335	    }
336	
337	    fn fail_start(&mut self, i: usize, now: Instant, why: String) {
338	        self.counts.attempts_failed += 1;
339	        let f = self.peers[i].failures;
340	        self.peers[i].failures += 1;
341	        self.say(why);
342	        self.peers[i].state = State::Idle {
343	            not_before: now + BACKOFF[f.min(BACKOFF.len() - 1)],
344	        };
345	    }
346	
347	    fn retransmit<P: Port>(&mut self, i: usize, port: &mut P, now: Instant) {
348	        let slot = self.peers[i].slot;
349	        let State::Pending(p) = &mut self.peers[i].state else {
350	            return;
351	        };
352	        // The exact same INIT bytes are resent (TECHNICAL_DESIGN.md 5.3).
353	        let result = port.exchange_tx(slot, p.initiator.init_bytes());
354	        p.retries += 1;
355	        let step = RETRANSMIT[p.retries.min(RETRANSMIT.len() - 1)];
356	        p.next_retry = now + step;
357	        if let Err(e) = result {
358	            let msg = format!("INIT retransmit failed: {e}");
359	            self.say(msg);
360	        }
361	    }
362	
363	    /// An INIT or RESPONSE the kernel forwarded. The kernel verified nothing but the
364	    /// outer source; everything cryptographic is checked here.
365	    pub fn on_exchange<P: Port>(&mut self, port: &mut P, ev: ExchangeRx, now: Instant) {
366	        let Some(i) = self.peers.iter().position(|p| p.slot == ev.slot) else {
367	            self.counts.rejected += 1;
368	            return;
369	        };
370	        self.peers[i].kernel_incarnation = ev.kernel_incarnation;
371	        match ev.bytes.get(4).copied() {
372	            Some(1) => self.on_init(i, port, &ev.bytes, now),
373	            Some(2) => self.on_response(i, port, &ev.bytes, now),
374	            _ => self.counts.rejected += 1,
375	        }
376	    }
377	
378	    fn stage_keys<P: Port>(
379	        &mut self,
380	        i: usize,
381	        port: &mut P,
382	        keys: &SessionKeys,
383	    ) -> Result<(), PortError> {
384	        let slot = self.peers[i].slot;
385	        let mut r = port.stage(slot, &self.peers[i].kernel_incarnation, keys);
386	        // The kernel replaced the peer (a disruptive change): learn the new identity once.
387	        if matches!(&r, Err(e) if e.errno == Some(116)) {
388	            let inc = port.kernel_incarnation(slot)?;
389	            self.peers[i].kernel_incarnation = inc;
390	            r = port.stage(slot, &inc, keys);
391	        }
392	        r
393	    }
394	
395	    fn on_init<P: Port>(&mut self, i: usize, port: &mut P, init: &[u8], now: Instant) {
396	        let name = self.peers[i].name.clone();
397	        if self.peers[i].role != Role::Responder {
398	            self.counts.rejected += 1;
399	            self.say(format!("ignored INIT from {name}: we are its initiator"));
400	            return;
401	        }
402	        let slot = self.peers[i].slot;
403	        // A byte-identical duplicate gets the identical cached RESPONSE, nothing else.
404	        if let Some(c) = &self.peers[i].cached
405	            && now.duration_since(c.at) < CACHE_LIFETIME
406	            && let Some(resp) = c.cache.replay_for(init)
407	        {
408	            let resp = resp.to_vec();
409	            self.counts.duplicates_answered += 1;
410	            if let Err(e) = port.exchange_tx(slot, &resp) {
411	                self.say(format!("cannot resend RESPONSE: {e}"));
412	            }
413	            return;
414	        }
415	        // The kernel issues the responder's locator, for the attempt of the INIT it delivered.
416	        let attempt = match parse_handshake(init) {
417	            Ok(d) => d.attempt_id,
418	            Err(e) => {
419	                self.counts.rejected += 1;
420	                self.say(format!("rejected INIT from {name}: {e}"));
421	                return;
422	            }
423	        };
424	        let responder_locator = match self.begin_attempt(i, port, Some(&attempt)) {
425	            Ok((_, locator)) => locator,
426	            Err(e) => {
427	                self.counts.rejected += 1;
428	                self.say(format!("cannot begin an attempt for {name}'s INIT: {e}"));
429	                return;
430	            }
431	        };
432	        let params = ResponderParams {
433	            incarnation: self.incarnation,
434	            responder_locator,
435	            path_budget: self.peers[i].path_budget,
436	            continuity_grant: None,
437	        };
438	        let public = self.peers[i].public;
439	        let responded = match respond(&self.key, &public, init, &params) {
440	            Ok(r) => r,
441	            Err(e) => {
442	                self.counts.rejected += 1;
443	                self.say(format!("rejected INIT from {name}: {e}"));
444	                return;
445	            }
446	        };
447	        // Install the keys before the RESPONSE leaves, so the initiator's first record
448	        // can already be opened; a failure to stage abandons the attempt.
449	        if let Err(e) = self.stage_keys(i, port, &responded.keys) {
450	            self.say(format!("cannot install keys for {name}: {e}"));
451	            return;
452	        }
453	        if let Err(e) = port.exchange_tx(slot, &responded.response) {
454	            self.say(format!("cannot send RESPONSE to {name}: {e}"));
455	        }
456	        self.peers[i].cached = Some(Cached {
457	            cache: ResponseCache::new(init, &responded.response),
458	            at: now,
459	        });
460	        self.peers[i].state = State::Established { since: now };
461	        self.peers[i].failures = 0;
462	        self.counts.established += 1;
463	        self.say(format!("tunnel to {name} established (responder)"));
464	    }
465	
466	    fn on_response<P: Port>(&mut self, i: usize, port: &mut P, response: &[u8], now: Instant) {
467	        let name = self.peers[i].name.clone();
468	        let State::Pending(p) = &mut self.peers[i].state else {
469	            // Not waiting for a RESPONSE (late duplicate, or never asked): drop it.
470	            self.counts.rejected += 1;
471	            return;
472	        };
473	        // A forged or stale RESPONSE leaves the attempt pending (Initiator::finish).
474	        let keys = match p.initiator.finish(response) {
475	            Ok(k) => k,
476	            Err(e) => {
477	                self.counts.rejected += 1;
478	                let note = match e {
479	                    ExchangeError::Completed => "late".to_owned(),
480	                    other => other.to_string(),
481	                };
482	                self.say(format!("rejected RESPONSE from {name}: {note}"));
483	                return;
484	            }
485	        };
486	        match self.stage_keys(i, port, &keys) {
487	            Ok(()) => {
488	                self.peers[i].state = State::Established { since: now };
489	                self.peers[i].failures = 0;
490	                self.counts.established += 1;
491	                self.say(format!("tunnel to {name} established (initiator)"));
492	            }
493	            Err(e) => {
494	                self.counts.attempts_failed += 1;
495	                self.say(format!("cannot install keys for {name}: {e}"));
496	                self.peers[i].state = State::Idle {
497	                    not_before: now + BACKOFF[0],
498	                };
499	            }
500	        }
501	    }
502	}
